import{_ as d,a0 as p,w as o,s as r,I as i,x as s,a1 as a,A as l,ao as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"5 个针对有经验用户的 Vim 实用技巧 | LCTT x X-CMD","titleTemplate":false,"description":"5 个针对有经验用户的 Vim 实用技巧 | LCTT (201701) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"5 个针对有经验用户的 Vim 实用技巧 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"5 个针对有经验用户的 Vim 实用技巧 | LCTT (201701) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201701/20140812 5 Vim Tips and Tricks for Experienced Users - part3","title":"5 个针对有经验用户的 Vim 实用技巧","tag":"201701","desc":""},"relativePath":"201701/20140812 5 Vim Tips and Tricks for Experienced Users - part3.md","filePath":"[post].md"}'),m={name:"201701/20140812 5 Vim Tips and Tricks for Experienced Users - part3.md"};function c(h,e,k,g,u,f){const t=p("Link");return o(),r("div",null,[e[20]||(e[20]=i("h1",{id:"_5-个针对有经验用户的-vim-实用技巧",tabindex:"-1"},[s("5 个针对有经验用户的 Vim 实用技巧 "),i("a",{class:"header-anchor",href:"#_5-个针对有经验用户的-vim-实用技巧","aria-label":"Permalink to “5 个针对有经验用户的 Vim 实用技巧”"},"​")],-1)),e[21]||(e[21]=i("p",null,[i("img",{src:"https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2014/08/vim-tips-tricks-featured.jpg",alt:"",title:"5 Vim Tips and Tricks for Experienced Userss"})],-1)),i("p",null,[e[1]||(e[1]=s("这篇文章是 ",-1)),a(t,{href:"https://www.maketecheasier.com/series/vim-user-guide/"},{default:l(()=>[...e[0]||(e[0]=[s("Vim 用户指南",-1)])]),_:1}),e[2]||(e[2]=s("系列文章中的一篇：",-1))]),i("ul",null,[i("li",null,[a(t,{href:"https://www.maketecheasier.com/start-with-vim-linux/"},{default:l(()=>[...e[3]||(e[3]=[s("Vim 初学者入门指南",-1)])]),_:1})]),i("li",null,[a(t,{href:"https://www.maketecheasier.com/vim-keyboard-shortcuts-cheatsheet/"},{default:l(()=>[...e[4]||(e[4]=[s("Vim 快捷键速查表",-1)])]),_:1})]),e[6]||(e[6]=i("li",null,"5 个针对有经验用户的 Vim 实用技巧",-1)),i("li",null,[a(t,{href:"https://www.maketecheasier.com/vim-tips-tricks-advanced-users/"},{default:l(()=>[...e[5]||(e[5]=[s("3 个针对高级用户的 Vim 编辑器实用技巧",-1)])]),_:1})])]),e[22]||(e[22]=n('<p>Vim 编辑器提供了很多的特性，要想全部掌握它们很困难。然而，花费更多的时间在命令行编辑器上总是有帮助的。毫无疑问，和 Vim 用户们进行交流能够让你更快地学习新颖有创造性的东西。</p><p><strong>注：</strong> 本文中用到的例子，使用的 Vim 版本是 7.4.52 。</p><h3 id="_1、-同时编辑多个文件" tabindex="-1">1、 同时编辑多个文件 <a class="header-anchor" href="#_1、-同时编辑多个文件" aria-label="Permalink to “1、 同时编辑多个文件”">​</a></h3><p>如果你是一名软件开发者或者把 Vim 作为主要的编辑器，那么可能很多时候你需要同时编辑多个文件。“紧跟（following）”是在同时编辑多个文件时可用的实用技巧。</p><p>不需要在多个 shell 界面中打开多个文件，你可以通过把多个文件的文件名作为 Vim 命令的参数从而在一个 shell 界面中打开多个文件。比如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>vim 文件1 文件2 文件3</span></span></code></pre></div><p>第一个文件（例子中的文件1）将成为当前文件并被读入缓冲区。</p><p>在编辑器中，使用 <code>:next</code> 或 <code>:n</code> 命令来移动到下一个文件，使用 <code>:prev</code> 或 <code>:N</code> 命令返回上一个文件。如果想直接切换到第一个文件或最后一个文件，使用 <code>:bf</code> 和 <code>:bl</code> 命令。特别地，如果想打开另外的文件并编辑，使用 <code>:e</code> 命令并把文件名作为参数（如果该文件不在当前目录中则需要完整路径做为参数）。</p><p>任何时候如果需要列出当前打开的所有文件，使用 <code>:ls</code> 命令。看下面展示的屏幕截图。</p><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2014/08/vim-ls.png" alt="vim-ls" title="vim-ls"></p><p>注意 ”%a” 表示文件在当前活动窗口，而 “#” 表示上一个活动窗口的文件。</p><h3 id="_2、-通过自动补全节约时间" tabindex="-1">2、 通过自动补全节约时间 <a class="header-anchor" href="#_2、-通过自动补全节约时间" aria-label="Permalink to “2、 通过自动补全节约时间”">​</a></h3><p>想节约时间并提高效率吗？使用缩写吧。使用它们能够快速写出文件中多次出现、复杂冗长的词。在 Vim 中缩写命令写就是 <code>ab</code> 。</p><p>比如，当你运行下面的命令以后：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:ab asap as soon as possible</span></span></code></pre></div><p>文件中出现的每一个 <code>asap</code> 都会被自动替换为 <code>as soon as possible</code> ，就像你自己输入的一样。</p><p>类似地，你可以使用缩写来更正常见的输入错误。比如，下面的命令</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:ab recieve receive</span></span></code></pre></div><p>将会自动更正拼写错误，就像你自己输入的一样。如果在一次特殊情况下你想阻止缩写展开或更正发生，那么你只需要在输入一个单词的最后一个字母以后按 <code>Ctrl + V</code> ，然后按空格键。</p><p>如果你想把刚才使用的缩写保存下来，从而当你下次使用 Vim 编辑器的时候可以再次使用，那么只需将完整的 <code>ab</code> 命令(没有起始的冒号)添加到　<code>/etc/vim/vimrc</code> 文件中。如果想删除某个缩写，你可以使用 <code>una</code> 命令。比如： <code>una asap</code> 。</p><h3 id="_3、-切分窗口便于复制-粘贴" tabindex="-1">3、 切分窗口便于复制/粘贴 <a class="header-anchor" href="#_3、-切分窗口便于复制-粘贴" aria-label="Permalink to “3、 切分窗口便于复制/粘贴”">​</a></h3><p>有时，你需要从一个文件将一段代码或文本的一部分复制到另一个。当使用 GUI（图形界面）编辑器的时候，这很容易实现，但是当使用一个命令行编辑器的时候，这就变得比较困难并且很费时间。幸运的是， Vim 提供了一种高效、节约时间的方式来完成这件事。</p><p>打开两个文件中的一个然后切分 Vim 窗口来打开另一个文件。可以通过使用 <code>split</code> 命令并以文件名作为参数来完成这件事。比如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:split test.c</span></span></code></pre></div><p>上面的命令将分离窗口并打开文件 “test.c”</p><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2014/08/vim-split.png" alt="vim-split" title="vim-split"></p><p>注意到 <code>split</code> 命令水平分离 Vim 窗口。如果你想垂直分离窗口，那么你可以使用 <code>vsplit</code> 命令。当同时打开了两个文件并从一个文件中复制好内容以后，按 <code>Ctrl + W</code> 切换到另一个文件，然后粘贴。</p><h3 id="_4、-保存一个没有权限的已编辑文件" tabindex="-1">4、 保存一个没有权限的已编辑文件 <a class="header-anchor" href="#_4、-保存一个没有权限的已编辑文件" aria-label="Permalink to “4、 保存一个没有权限的已编辑文件”">​</a></h3><p>有时候当你对一个文件做了大量更改以后才会意识到你对该文件仅有 <code>只读</code> 权限。</p><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2014/08/vim-sudo.png" alt="vim-sudo" title="vim-sudo"></p><p>虽然把文件关闭，获取权限以后再重新打开是一种解决方法。但是如果你已经做了大量更改，这样做会很浪费时间，因为在这个过程中所有的更改都会丢失。 Vim 提供了一种方式来处理这种情况：你可以在编辑器中在保存文件前更改文件权限。命令是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:w !sudo tee %</span></span></code></pre></div><p>这个命令将会向你询问密码，就像在命令行中使用 <code>sudo</code> 一样，然后就能保存更改。</p><p><strong>一个相关的技巧</strong>：在 Vim 中编辑一个文件的时候，如果想快速进入命令行提示符，可以在编辑器中运行 <code>:sh</code> 命令，从而你将进入一个交互的 shell 中。完成以后，运行 <code>exit</code> 命令可以快速回到 Vim 模式中。</p><h3 id="_5、-在复制-粘贴过程中保持缩进" tabindex="-1">5、 在复制/粘贴过程中保持缩进 <a class="header-anchor" href="#_5、-在复制-粘贴过程中保持缩进" aria-label="Permalink to “5、 在复制/粘贴过程中保持缩进”">​</a></h3><p>大多数有经验的程序员在 Vim 上工作时都会启用自动缩进。虽然这是一个节约时间的做法，但是在粘贴一段已经缩进了的代码的时候会产生新的问题。比如，下图是我把一段已缩进代码粘贴到一个在自动缩进的 Vim 编辑器中打开的文件中时遇到的问题：</p><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2014/08/vim-indentation.png" alt="vim-indentation" title="vim-indentation"></p><p>这个问题的解决方法是 <code>pastetoggle</code> 选项。在 <code>/etc/vim/vimrc</code> 文件中加入下面这行内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>set pastetoggle=&lt;F2&gt;</span></span></code></pre></div><p>然后当你在 <code>插入</code> 模式中准备粘贴代码前先按 <code>F2</code> 键，就不会再出现上图中的问题，这样会保留原始的缩进。注意，你可以用其他的任何键来代替 <code>F2</code>，如果它已经映射到了别的功能上。</p><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to “结论”">​</a></h3><p>更进一步的提高你的 Vim 编辑器技巧的唯一方法是，在你日复一日的工作中使用命令行编辑器。留意那些耗时多的操作，然后尝试去寻找是否有编辑器命令可以很快地完成这个操作。</p><hr>',43)),i("p",null,[e[8]||(e[8]=s("via: ",-1)),a(t,{href:"https://www.maketecheasier.com/vim-tips-tricks-for-experienced-users/"},{default:l(()=>[...e[7]||(e[7]=[s("https://www.maketecheasier.com/vim-tips-tricks-for-experienced-users/",-1)])]),_:1})]),i("p",null,[e[12]||(e[12]=s("作者：",-1)),a(t,{href:"https://www.maketecheasier.com/author/himanshu/"},{default:l(()=>[...e[9]||(e[9]=[s("Himanshu Arora",-1)])]),_:1}),e[13]||(e[13]=s(" 译者：",-1)),a(t,{href:"https://github.com/ucasFL"},{default:l(()=>[...e[10]||(e[10]=[s("ucasFL",-1)])]),_:1}),e[14]||(e[14]=s(" 校对：",-1)),a(t,{href:"https://github.com/wxy"},{default:l(()=>[...e[11]||(e[11]=[s("wxy",-1)])]),_:1})]),i("p",null,[e[17]||(e[17]=s("本文由 ",-1)),a(t,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...e[15]||(e[15]=[s("LCTT",-1)])]),_:1}),e[18]||(e[18]=s(" 原创编译，",-1)),a(t,{href:"https://linux.cn/"},{default:l(()=>[...e[16]||(e[16]=[s("Linux中国",-1)])]),_:1}),e[19]||(e[19]=s(" 荣誉推出",-1))])])}const V=d(m,[["render",c]]);export{x as __pageData,V as default};
